ACPI: processor: Fix previous acpi_processor_errata_piix4()
 fix

After commi f132e089fe89 ("ACPI: processor: Fix NULL-pointer dereference
in acpi_processor_errata_piix4()"), device pointers may be dereferenced
after dropping references to the device objects pointed to by them,
which may cause a use-after-free to occur.

Moreover, debug messages about enabling the errata may be printed
if the errata flags corresponding to them are unset.

Address all of these issues by moving message printing to the points
in the code where the errata flags are set.

Fixes: f132e089fe89 ("ACPI: processor: Fix NULL-pointer dereference in acpi_processor_errata_piix4()")
Reported-by: Guenter Roeck <linux@roeck-us.net>
Closes: https://lore.kernel.org/linux-acpi/938e2206-def5-4b7a-9b2c-d1fd37681d8a@roeck-us.net/
Reviewed-by: Guenter Roeck <linux@roeck-us.net>
Signed-off-by: Rafael J. Wysocki <rafael.j.wysocki@intel.com>
Link: https://patch.msgid.link/5975693.DvuYhMxLoT@rafael.j.wysocki

Here is the root cause:
After the previous fix, debug messages were printed after pci_dev_put() calls, leading to use-after-free, and were also printed unconditionally even when errata flags were not set.

Here is the patch:

 static int acpi_processor_errata_piix4(struct pci_dev *dev)
 {
 	u8 value1 = 0;
 	u8 value2 = 0;
 	struct pci_dev *ide_dev = NULL, *isa_dev = NULL;


 	if (!dev)
 		return -EINVAL;

 	/*
 	 * Note that 'dev' references the PIIX4 ACPI Controller.
 	 */

 	switch (dev->revision) {
 	case 0:
 		dev_dbg(&dev->dev, "Found PIIX4 A-step\n");
 		break;
 	case 1:
 		dev_dbg(&dev->dev, "Found PIIX4 B-step\n");
 		break;
 	case 2:
 		dev_dbg(&dev->dev, "Found PIIX4E\n");
 		break;
 	case 3:
 		dev_dbg(&dev->dev, "Found PIIX4M\n");
 		break;
 	default:
 		dev_dbg(&dev->dev, "Found unknown PIIX4\n");
 		break;
 	}

 	switch (dev->revision) {

 	case 0:		/* PIIX4 A-step */
 	case 1:		/* PIIX4 B-step */
 		/*
 		 * See specification changes #13 ("Manual Throttle Duty Cycle")
 		 * and #14 ("Enabling and Disabling Manual Throttle"), plus
 		 * erratum #5 ("STPCLK# Deassertion Time") from the January
 		 * 2002 PIIX4 specification update.  Applies to only older
 		 * PIIX4 models.
 		 */
 		errata.piix4.throttle = 1;
 		fallthrough;

 	case 2:		/* PIIX4E */
 	case 3:		/* PIIX4M */
 		/*
 		 * See erratum #18 ("C3 Power State/BMIDE and Type-F DMA
 		 * Livelock") from the January 2002 PIIX4 specification update.
 		 * Applies to all PIIX4 models.
 		 */

 		/*
 		 * BM-IDE
 		 * ------
 		 * Find the PIIX4 IDE Controller and get the Bus Master IDE
 		 * Status register address.  We'll use this later to read
 		 * each IDE controller's DMA status to make sure we catch all
 		 * DMA activity.
 		 */
 		ide_dev = pci_get_subsys(PCI_VENDOR_ID_INTEL,
 				     PCI_DEVICE_ID_INTEL_82371AB,
 				     PCI_ANY_ID, PCI_ANY_ID, NULL);
 		if (ide_dev) {
 			errata.piix4.bmisx = pci_resource_start(ide_dev, 4);
+			if (errata.piix4.bmisx)
+				dev_dbg(&ide_dev->dev,
+					"Bus master activity detection (BM-IDE) erratum enabled\n");
+
 			pci_dev_put(ide_dev);
 		}

 		/*
 		 * Type-F DMA
 		 * ----------
 		 * Find the PIIX4 ISA Controller and read the Motherboard
 		 * DMA controller's status to see if Type-F (Fast) DMA mode
 		 * is enabled (bit 7) on either channel.  Note that we'll
 		 * disable C3 support if this is enabled, as some legacy
 		 * devices won't operate well if fast DMA is disabled.
 		 */
 		isa_dev = pci_get_subsys(PCI_VENDOR_ID_INTEL,
 				     PCI_DEVICE_ID_INTEL_82371AB_0,
 				     PCI_ANY_ID, PCI_ANY_ID, NULL);
 		if (isa_dev) {
 			pci_read_config_byte(isa_dev, 0x76, &value1);
 			pci_read_config_byte(isa_dev, 0x77, &value2);
-			if ((value1 & 0x80) || (value2 & 0x80))
+			if ((value1 & 0x80) || (value2 & 0x80)) {
 				errata.piix4.fdma = 1;
+				dev_dbg(&isa_dev->dev,
+					"Type-F DMA livelock erratum (C3 disabled)\n");
+			}
 			pci_dev_put(isa_dev);
 		}

 		break;
 	}

-	if (ide_dev)
-		dev_dbg(&ide_dev->dev, "Bus master activity detection (BM-IDE) erratum enabled\n");
-
-	if (isa_dev)
-		dev_dbg(&isa_dev->dev, "Type-F DMA livelock erratum (C3 disabled)\n");
-
 	return 0;
 }



